    private static Object[][] compose(Object[] ... sets) {
        int size = 1;
        for (int i = 0; i < sets.length; i++)
            size += sets[i].length;

        Object[][] all = new Object[size][sets.length];

        for (int i = 0; i < sets.length; i++)
            all[0][i] = sets[i][0];

        int off = 1;
        for (int i = 0; i < sets.length; i++) {
            for (int j = 0; j < sets[i].length; j++, off++) {
                for (int k = 0; k < sets.length; k++) {
                    all[off][k] = i == k ? sets[k][j] : sets[k][0];
                }
            }
        }

        return all;
    }

